const projects = {
  together: {name:'Together',label:'macOS application',intro:'Shared tasks, wishes, daily gifts and expenses in one macOS app.',features:['Shared tasks and wishes','Expense ledger and reserve balances','Local data and peer synchronization'],note:'Sync requires both devices to be online.',link:'https://github.com/Diamond-Fountain-Works/Together'},
  alto: {name:'Alto Cloud',label:'macOS prototype',intro:'Nearby-device discovery and interfaces for sharing files on the same Wi-Fi.',features:['Bonjour device discovery','Quick Send and Shared Cloud interfaces','One-time drop concept'],note:'Prototype. File transfer is currently simulated.'},
  gre: {name:'GRE Words',label:'macOS application',intro:'A vocabulary tool with word roots, study cards and a personal wordbook.',features:['Draggable word-root graphs','Search, pronunciation and saved words','Menu bar study cards'],note:'Candidate word-form relationships are marked as unverified.'},
  pet: {name:'MyPixelPet',label:'macOS MVP',intro:'A transparent desktop pet with dragging, feeding and interaction.',features:['Floating pet window','Hunger and happiness states','Menu bar, always-on-top and click-through controls'],note:'The current implementation focuses on macOS.'}
};
const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
document.querySelectorAll('.filter').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.filter').forEach(el=>{el.classList.toggle('active',el===button);el.setAttribute('aria-pressed',String(el===button))});document.querySelectorAll('.project').forEach(el=>{el.hidden=button.dataset.filter!=='all'&&el.dataset.category!==button.dataset.filter;el.classList.add('visible')});}));
const dialog=document.querySelector('#project-dialog');let openedBy=null;
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{const p=projects[button.dataset.project];openedBy=button;dialog.querySelector('.dialog-content').innerHTML=`<span class="dialog-status">${p.label}</span><h2 id="dialog-title">${p.name}</h2><p>${p.intro}</p>${p.image?`<img src="${p.image}" alt="Together application interface">`:''}<h3>Features</h3><ul>${p.features.map(f=>`<li>${f}</li>`).join('')}</ul><p class="dialog-note">${p.note}</p>${p.link?`<a href="${p.link}" target="_blank" rel="noopener noreferrer">View source on GitHub <span aria-hidden="true">↗</span></a>`:''}`;dialog.showModal();dialog.scrollTop=0;}));
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>openedBy?.focus());
document.querySelector('#year').textContent=new Date().getFullYear();
// Soft, moving cyan halos complement the grain and black blur of the cover direction.
const canvas=document.querySelector('#water'),ctx=canvas.getContext('2d'),hero=document.querySelector('.hero');let w=0,h=0,targetX=.65,targetY=.5,pointerX=.65,pointerY=.5,frame=0,heroVisible=true;
function resize(){w=hero.clientWidth;h=hero.clientHeight;const dpr=Math.min(window.devicePixelRatio||1,1.5);canvas.width=w*dpr;canvas.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}new ResizeObserver(resize).observe(hero);new IntersectionObserver(entries=>heroVisible=entries[0].isIntersecting).observe(hero);
hero.addEventListener('pointermove',e=>{const r=hero.getBoundingClientRect();targetX=(e.clientX-r.left)/r.width;targetY=(e.clientY-r.top)/r.height});hero.addEventListener('pointerleave',()=>{targetX=.65;targetY=.5});
function draw(now){requestAnimationFrame(draw);if(!heroVisible||document.hidden||document.documentElement.classList.contains('intro-playing'))return;if(++frame%2)return;const t=now*.00012;pointerX+=(targetX-pointerX)*.045;pointerY+=(targetY-pointerY)*.045;ctx.clearRect(0,0,w,h);for(let i=0;i<3;i++){ctx.save();ctx.translate(w*(.23+i*.28+Math.sin(t+i)*.08)+(pointerX-.5)*80,h*(.4+Math.cos(t+i)*.1)+(pointerY-.5)*70);ctx.rotate(-.4+Math.sin(t)*.13);ctx.scale(.36,1.7);const glow=ctx.createRadialGradient(0,0,w*.08,0,0,w*.2);glow.addColorStop(0,'rgba(94,255,204,0)');glow.addColorStop(.65,'rgba(94,255,204,.35)');glow.addColorStop(1,'rgba(94,255,204,0)');ctx.fillStyle=glow;ctx.fillRect(-w*.25,-w*.25,w*.5,w*.5);ctx.restore()}}requestAnimationFrame(draw);
